    $('#activeMetric').textContent=state.engagements.filter(x=>['Active','Planning','Awaiting approval','Reporting'].includes(x.status)).length;$('#assetMetric').textContent=state.assets.length;$('#approvalMetric').textContent=state.authorizations.filter(x=>x.status==='Pending').length;$('#riskMetric').textContent=state.findings.filter(x=>['Critical','High'].includes(x.severity)&&['Open','In progress'].includes(x.status)).length;
